fn 合計(幅: Int, 高さ: Int) -> Int {
    let 結果 = 幅 + 高さ
    return 結果
}
fn 未使用() -> Int { return 1 }
fn main() -> Int { print(合計(40, 2))
 return 0
}

let 基準 = 40
fn 加算(値: Int) -> Int { return 値 + 基準 }
fn main() -> Int { print(加算(基準))
return 0
}

fn 適用(操作: Int -> Int, 値: Int) -> Int { return 操作(値) }
fn 増加(値: Int) -> Int { return 値 + 1 }
fn main() -> Int { print(適用(増加, 41))
return 0
}

fn 合計(横 幅: Int, 縦 高さ: Int) -> Int { return 幅 + 高さ }
fn main() -> Int { print(合計(縦: 2, 横: 40))
return 0
}

type 荷物 = { 数: Int, 有効: Bool, }
fn 読む(箱: 荷物) -> Int { if 箱.有効 { return 箱.数 }
 return 0
}
fn 作る(数: Int) -> 荷物 { let 箱: 荷物 = 荷物(有効: true, 数: 数)
return 箱
}
fn main() -> Int { let 箱: 荷物 = 作る(42)
print(読む(箱))
return 0
}

fn café(q́: Int) -> Int { return q́ + 1 }
fn 日本(値: Int) -> Int { return café(値) }
fn 𐐀(値: Int) -> Int { return 日本(値) }
fn main() -> Int { print(𐐀(41))
return 0
}

fn stage2_unicode_scalar_at(値: Int) -> Int { return 値 + 1 }
fn stage2_same_file(値: Int) -> Int { return 値 + 1 }
fn main() -> Int { print(stage2_same_file(stage2_unicode_scalar_at(40)))
return 0
}

type 固定[const 桁: Int] = { 数: Int, }
fn 保持(値: 固定[2]) -> 固定[2] { return 値 }
fn main() -> Int { let 値: 固定[2] = 固定[2](数: 42)
let 結果: 固定[2] = 保持(値)
print(結果.数)
return 0
}
